const svg = document.currentScript.ownerSVGElement;
const data = splinely.sourceProject; // decoded once by the runtime (binary or JSON metadata)
const machine = data.stateMachines.length ? splinely.machine('gallery') : null;
const status = svg.querySelector('[id="status"]');
let paused = [], pauseRequested = false;
function describe() {
  status.textContent = (machine ? 'State: ' + machine.state : 'Water drop') +
    ' · ' + (splinely.timeline.playing ? 'playing' : 'paused');
}
function start() {
  pauseRequested = false;
  for (const id of paused) splinely.clip(id).play();
  paused = []; splinely.timeline.play(); describe();
}
function pause() {
  pauseRequested = true;
  if (splinely.timeline.playing) {
    paused = data.clips.filter(c => splinely.clip(c.id).playing).map(c => c.id);
    splinely.timeline.pause();
  }
  describe();
}
splinely.on('showcase.start', start);
splinely.on('showcase.pause', pause);
splinely.on('state.change', () => {
  // Pausing synchronizes the wall clock. A queued clip.end may enter the next
  // state after the Pause handler returns; hold that new clip, not the old one.
  if (pauseRequested) {
    paused = data.clips.filter(c => splinely.clip(c.id).playing).map(c => c.id);
    splinely.timeline.pause();
  }
  describe();
});
splinely.on('error', () => { status.textContent = 'Runtime error · inspect diagnostics'; });
describe();
